const $=s=>document.querySelector(s);
const ICONS={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',arrow:'<path d="M19 12H5m6-6-6 6 6 6"/>',truck:'<path d="M2 5h12v12H2ZM14 9h4l4 5v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',return:'<path d="M5 8h9a6 6 0 0 1 0 12h-3M9 3 4 8l5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="currentColor"/><circle cx="15" cy="17" r="2" fill="currentColor"/>',box:'<path d="m3 7 9-5 9 5v11l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v11M7 4l10 5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.bag}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('en',{minimumFractionDigits:0,maximumFractionDigits:2})+' د.أ';
const product=id=>PRODUCTS.find(p=>p.id===id);const catName=id=>CATEGORIES.find(c=>c[0]===id)?.[1]||'كل القطع';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let cart=read('loop-store-cart',[]);if(!Array.isArray(cart))cart=[];cart=cart.filter(c=>product(c.id)&&product(c.id).sizes.includes(c.size)&&!product(c.id).unavailable.includes(c.size)&&Number.isInteger(c.qty)&&c.qty>0).map(c=>({...c,qty:Math.min(c.qty,product(c.id).stock)}));
let favorites=read('loop-store-favorites',[]);if(!Array.isArray(favorites))favorites=[];favorites=favorites.filter(id=>product(id));let orders=read('loop-store-orders',[]);if(!Array.isArray(orders))orders=[];
let coupon=read('loop-store-coupon','')==='LOOP10'?'LOOP10':'',delivery='standard',lastFocus=null,toastTimer,quickId=null,chosenSize=null,checkoutStep=1,checkoutData={},visibleCount=12,heroIndex=0,filtersExpanded=false;
function persist(){try{localStorage.setItem('loop-store-cart',JSON.stringify(cart));localStorage.setItem('loop-store-favorites',JSON.stringify(favorites));localStorage.setItem('loop-store-coupon',JSON.stringify(coupon));localStorage.setItem('loop-store-orders',JSON.stringify(orders))}catch{toast('تعذّر الحفظ في المتصفح، يمكنك متابعة التصفح.')}updateHeader()}
function totals(){const subtotal=cart.reduce((s,c)=>s+product(c.id).price*c.qty,0);const discount=coupon==='LOOP10'?Math.round(subtotal*10)/100:0;const net=+(subtotal-discount).toFixed(2);const shipping=!cart.length?0:delivery==='express'?7:net>=75?0:3;return{subtotal,discount,net,shipping,total:+(net+shipping).toFixed(2)}}
let spriteSerial=0;
function sprite(p,extra=''){if(p.atlas===1){const row=Math.floor(p.cell/4),y=[0,435,665][row],h=[435,230,359][row],clip='sprite-'+(++spriteSerial);return `<div class="sprite atlas1 ${extra}" style="filter:${p.filter};background:none"><svg viewBox="${(p.cell%4)*384} ${y} 384 ${h}" style="width:100%;height:100%;stroke:none;overflow:hidden" role="img" aria-label="${p.name} ${p.color}"><defs><clipPath id="${clip}" clipPathUnits="userSpaceOnUse"><rect x="${(p.cell%4)*384}" y="${y}" width="384" height="${h}"/></clipPath></defs><image href="assets/catalog.png" x="0" y="0" width="1536" height="1024" clip-path="url(#${clip})"/></svg></div>`}return `<div class="sprite ${extra}" role="img" aria-label="${p.name} ${p.color}" style="background-position:${(p.cell%3)*50}% ${Math.floor(p.cell/3)*100}%;filter:${p.filter}"></div>`}
function price(p){return `<span class="price">${money(p.price)}${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</span>`}
function heart(p,cls='heart'){const active=favorites.includes(p.id);return `<button class="${cls}${active?' selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${active?'إزالة من':'إضافة إلى'} المفضلة: ${p.name}" aria-pressed="${active}">${icon('heart')}</button>`}
function card(p){return `<article class="product-card"><div class="product-image">${p.oldPrice?`<span class="product-badge sale">−${Math.round((1-p.price/p.oldPrice)*100)}%</span>`:p.new?'<span class="product-badge">وصل حديثاً</span>':''}${heart(p)}<a href="#product/${p.id}" aria-label="${p.name} ${p.color}">${sprite(p)}</a><button class="quick-add" data-action="quick" data-id="${p.id}">إضافة سريعة <span>+</span></button></div><div class="product-info"><span class="card-category">${catName(p.category)} / ${p.color}</span><h3><a href="#product/${p.id}">${p.name}</a></h3><div class="card-bottom">${price(p)}<div class="swatches" aria-label="لونان متاحان"><span class="swatch"></span><span class="swatch alt"></span></div></div></div></article>`}
function updateHeader(){$('#cartCount').textContent=cart.reduce((s,c)=>s+c.qty,0);$('#favoriteLink').innerHTML=icon('heart');$('#favoriteLink').title='المفضلة ('+favorites.length+')'}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function legacyHome(){const cats=[['tops',1],['outerwear',5],['bottoms',7],['shoes',10],['bags',14],['accessories',16]];return `<section class="hero"><div class="hero-copy"><span class="eyebrow">THE NEW EVERYDAY / FALL 2026</span><h1>أسلوبك.<br>خارج <em>المألوف.</em></h1><p>قطع مختارة بعناية، من أساسيات كل يوم إلى التفاصيل التي تصنع الفرق. اكتشف ما يشبهك.</p><div class="hero-actions"><a class="btn" href="#catalog">اكتشف المجموعة ${icon('arrow')}</a><a class="btn outline" href="#room/men">الصالة التفاعلية ↗</a></div><div class="hero-foot"><span>36 قطعة للاكتشاف</span><span>01 — مجموعة الخريف</span></div></div><div class="hero-art"><div class="hero-rail"></div><div class="hero-piece left">${sprite(PRODUCTS[0])}</div><div class="hero-piece" id="heroPiece">${sprite(PRODUCTS[2])}</div><div class="hero-piece right">${sprite(PRODUCTS[3])}</div><span class="hero-word">loop®</span><a href="#product/p3" id="heroTag" class="hero-tag">تيشيرت أسيد / أزرق<span>اكتشف القطعة ↗</span></a><div class="hero-dot"><button data-action="hero" data-index="0" class="active" aria-label="عرض تيشيرت أسيد">01</button><button data-action="hero" data-index="1" aria-label="عرض كارديغان لاين">02</button><button data-action="hero" data-index="2" aria-label="عرض جاكيت سيج">03</button></div></div></section><div class="value-strip"><div>${icon('box')}<span>تشكيلة لكل يوم</span></div><div>${icon('heart')}<span>احفظ القطع التي تحبّها</span></div><div>${icon('check')}<span>تجربة تسوّق بلا دفع فعلي</span></div></div><div class="container"><section class="section"><div class="section-head"><div><span class="eyebrow">FIND YOUR NEXT FAVORITE</span><h2>تسوّق على طريقتك</h2></div><a class="text-link" href="#catalog">جميع الأقسام ←</a></div><div class="categories">${cats.map(([c,i])=>`<a class="category-card" href="#catalog?category=${c}"><div class="category-img">${sprite(PRODUCTS[i])}</div><div><span>${({tops:'تيشيرتات',outerwear:'جاكيتات',bottoms:'بناطيل وتنانير',shoes:'أحذية',bags:'حقائب',accessories:'إكسسوارات'})[c]}</span><small>${String(PRODUCTS.filter(p=>p.category===c).length).padStart(2,'0')}</small></div></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">JUST LANDED</span><h2>جديد يستحق الاكتشاف</h2></div><a class="text-link" href="#catalog?new=1">شاهد الجديد ←</a></div><div class="product-grid">${[2,5,7,10].map(i=>card(PRODUCTS[i])).join('')}</div></section><section class="editorial"><div class="editorial-copy"><span class="eyebrow">LESS NOISE. MORE YOU.</span><h2>التفاصيل الصغيرة.<br>الفرق الكبير.</h2><p>حقيبة ترافق يومك، وحذاء يكمّل إطلالتك. اختيارات بسيطة، بحضور مختلف.</p><a class="btn acid" href="#catalog?category=bags">اكتشف الحقائب ${icon('arrow')}</a></div><div class="editorial-art">${sprite(PRODUCTS[15])}${sprite(PRODUCTS[17],'second')}<span class="editorial-label">EVERYDAY, REDEFINED.</span></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE LOOP EDIT</span><h2>اختياراتنا لك</h2></div><a class="text-link" href="#catalog">المجموعة كاملة ←</a></div><div class="product-grid">${[0,4,11,14,8,13,16,21].map(i=>card(PRODUCTS[i])).join('')}</div></section><section class="studio-banner"><div><span class="eyebrow">A DIFFERENT WAY TO EXPLORE</span><h2>ادخل المساحة. جرّب تجربة مختلفة.</h2><p>تجوّل بين الملابس المعلّقة، اسحب لاكتشاف القطع، ثم اختر ما يناسبك.</p></div><a class="btn" href="#room/men">ادخل الصالة التفاعلية ↗</a></section></div>`}
function params(){return new URLSearchParams((location.hash.split('?')[1]||''))}
function catalogURL(updates,clear=false){const q=clear?new URLSearchParams():params();Object.entries(updates).forEach(([k,v])=>v?q.set(k,v):q.delete(k));return '#catalog'+(q.size?'?'+q.toString():'')}
function filteredProducts(q=params()){return PRODUCTS.filter(p=>(!q.get('category')||p.category===q.get('category'))&&(!q.get('gender')||p.gender.includes(q.get('gender')))&&(!q.get('new')||p.new)&&(!q.get('sale')||p.oldPrice)&&(!q.get('size')||(p.sizes.includes(q.get('size'))&&!p.unavailable.includes(q.get('size'))))&&(!q.get('max')||p.price<=+q.get('max'))&&(!q.get('q')||normalize(`${p.name} ${p.color} ${catName(p.category)} ${p.sku}`).includes(normalize(q.get('q'))))).sort((a,b)=>q.get('sort')==='low'?a.price-b.price:q.get('sort')==='high'?b.price-a.price:q.get('sort')==='new'?Number(b.new)-Number(a.new):0)}
function normalize(s){return s.toLowerCase().replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[ًٌٍَُِّْ]/g,'').trim()}
function catalog(){const q=params(),items=filteredProducts(q),title=q.get('q')?'نتائج البحث':q.get('category')?catName(q.get('category')):q.get('new')?'وصل حديثاً':q.get('sale')?'اختيارات بسعر أقل':q.get('gender')==='men'?'المجموعة الرجالية':q.get('gender')==='women'?'المجموعة النسائية':'كل القطع. كل الاحتمالات.';return `<div class="container"><div class="page-heading"><div class="breadcrumb"><a href="#home">الرئيسية</a><span>/</span><span>المتجر</span></div><span class="eyebrow">THE COMPLETE COLLECTION</span><h1>${title}</h1><p>${q.get('q')?'نتائج البحث عن «'+esc(q.get('q'))+'»':'من القطع الأساسية إلى التفاصيل المميزة. ابحث عن أسلوبك هنا.'}</p></div><nav class="catalog-tabs" aria-label="أقسام المنتجات">${CATEGORIES.map(([id,name])=>`<a href="${catalogURL({category:id==='all'?'':id})}" class="${(q.get('category')||'all')===id?'active':''}">${name}</a>`).join('')}</nav><div class="catalog-toolbar"><button class="filter-toggle" data-action="filters" aria-expanded="${filtersExpanded}">${icon('filter')} تصفية</button><span class="result-count">${items.length} منتج</span><div><label for="sort">الترتيب حسب:</label><select id="sort" aria-label="ترتيب المنتجات"><option value="featured" ${q.get('sort')==='featured'?'selected':''}>اختيارات LOOP</option><option value="low" ${q.get('sort')==='low'?'selected':''}>السعر: من الأقل للأعلى</option><option value="high" ${q.get('sort')==='high'?'selected':''}>السعر: من الأعلى للأقل</option><option value="new" ${q.get('sort')==='new'?'selected':''}>الأحدث أولاً</option></select></div></div><div class="active-filters">${[...q].filter(([k])=>k!=='sort').map(([k,v])=>`<button data-action="remove-filter" data-key="${esc(k)}">${esc(({category:catName(v),gender:v==='men'?'رجالي':'نسائي',new:'وصل حديثاً',sale:'العروض',q:'بحث: '+v,size:'مقاس '+v,max:'حتى '+money(v)})[k]||v)} ×</button>`).join('')}</div><div class="catalog-layout"><aside class="filters ${filtersExpanded?'open':''}" id="filters"><div class="filter-group"><h3>المجموعة</h3>${[['','الكل'],['men','رجالي'],['women','نسائي']].map(([v,l])=>`<label><input type="radio" name="gender" value="${v}" ${q.get('gender')===v||!q.get('gender')&&!v?'checked':''}>${l}</label>`).join('')}</div><div class="filter-group"><h3>السعر</h3><input id="priceRange" type="range" min="19" max="100" value="${q.get('max')||100}" aria-label="أعلى سعر"><div class="filter-price"><span>19 د.أ</span><output id="priceOutput">${money(q.get('max')||100)}</output></div></div><div class="filter-group"><h3>المقاس</h3><select id="sizeFilter" aria-label="تصفية حسب المقاس"><option value="">جميع المقاسات</option>${['S','M','L','XL','37','38','39','40','41','42','43','44','موحّد'].map(s=>`<option ${q.get('size')===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="filter-group"><h3>اكتشف المزيد</h3><label><input type="checkbox" id="saleFilter" ${q.get('sale')?'checked':''}>القطع المخفّضة</label><label><input type="checkbox" id="newFilter" ${q.get('new')?'checked':''}>وصل حديثاً</label></div><button class="clear-filters" data-action="reset-filters">مسح كل الفلاتر</button></aside><div><div class="product-grid">${items.length?items.slice(0,visibleCount).map(card).join(''):empty('ما لقينا قطع بهذه المواصفات','جرّب تغيير البحث أو تخفيف الفلاتر.','مسح الفلاتر','#catalog')}</div>${items.length>visibleCount?`<div class="load-more"><p>عرض ${visibleCount} من ${items.length} قطعة</p><button class="btn outline" data-action="more">عرض المزيد +</button></div>`:items.length?'<div class="list-footer">وصلت إلى نهاية المجموعة. قد تكون قطعتك المفضلة بالأعلى ↑</div>':''}</div></div></div>`}
function empty(title,desc,label,href){return `<div class="empty-state">${icon('bag')}<h2>${title}</h2><p>${desc}</p><a class="btn" href="${href}">${label}</a></div>`}
function productOptions(p,quick=false){return `<div class="product-summary" data-product="${p.id}"><span class="eyebrow">${p.sku} / ${catName(p.category)}</span><h1>${p.name}</h1>${price(p)}<p>${p.description}</p>${quick?'':`<div class="product-meta"><span>مجموعة تجريبية</span><span>${p.stock<=3?'كمية محدودة في النموذج':'متاح في النموذج'}</span></div>`}<div class="option-title"><span>اللون: <strong>${p.color}</strong></span></div><div class="color-options">${PRODUCTS.filter(x=>x.base===p.base).map(x=>`<a class="${x.id===p.id?'active':''}" href="#product/${x.id}">${x.color}</a>`).join('')}</div><div class="option-title"><span>اختر المقاس</span><button data-action="size-guide">دليل المقاسات ↗</button></div><div class="size-options">${p.sizes.map(s=>`<button data-action="size" data-size="${s}" ${p.unavailable.includes(s)?'disabled title="غير متوفر"':''} aria-pressed="false">${s}</button>`).join('')}</div><p class="size-error" aria-live="polite"></p><div class="buy-row"><button class="btn" data-action="add" data-id="${p.id}">أضف إلى الحقيبة ${icon('bag')}</button>${heart(p,'icon-btn')}</div>${quick?`<a class="text-link" style="display:inline-block;margin-top:15px" href="#product/${p.id}">كل تفاصيل القطعة ←</a>`:`<div class="product-notes"><span>${icon('box')} كتالوج توضيحي</span><span>${icon('check')} لا يتم تحصيل مبالغ</span></div><details open><summary>التفاصيل والخامة</summary><p>${p.material}. اللون: ${p.color}. الصور والأسعار والمخزون بيانات تجريبية لأغراض المعاينة.</p></details><details><summary>العناية بالقطعة</summary><p>${p.category==='shoes'||p.category==='bags'||p.category==='accessories'?'تنظيف موضعي بقطعة قماش ناعمة، والابتعاد عن مصادر الحرارة.':'غسيل لطيف بماء بارد مع الألوان المشابهة. تجنّب المبيّضات والتجفيف بدرجات حرارة عالية.'} هذه إرشادات توضيحية، ويُعتمد ملصق المنتج الفعلي عند توفيره.</p></details><details><summary>الشحن والاستبدال</summary><p>يمكنك تجربة حساب الشحن وخطوات الطلب داخل النموذج. لا توجد خدمة توصيل أو سياسة استبدال تجارية مفعّلة حالياً.</p><a class="text-link" href="#help?s=shipping">التفاصيل ←</a></details>`}</div>`}
function productPage(id){const p=product(id);if(!p)return '<div class="container">'+empty('هذه القطعة غير موجودة','اكتشف باقي المجموعة.','العودة للمتجر','#catalog')+'</div>';return `<div class="container"><div class="page-heading"><div class="breadcrumb"><a href="#home">الرئيسية</a><span>/</span><a href="#catalog?category=${p.category}">${catName(p.category)}</a><span>/</span><span>${p.name}</span></div></div><section class="product-page"><div class="product-gallery" id="gallery">${sprite(p)}${p.oldPrice?'<span class="product-badge sale">عرض خاص</span>':''}<button class="zoom-btn" data-action="zoom">تكبير الصورة +</button></div>${productOptions(p)}</section><section class="section"><div class="section-head"><div><span class="eyebrow">COMPLETE THE LOOK</span><h2>قطع تكمل اختيارك</h2></div><a href="#catalog" class="text-link">كل المجموعة ←</a></div><div class="product-grid">${PRODUCTS.filter(x=>x.id!==p.id&&x.base!==p.base).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,4).map(card).join('')}</div></section></div>`}
function favoritePage(){return `<div class="container"><div class="page-heading"><span class="eyebrow">SAVED FOR LATER</span><h1>قطع على ذوقك.</h1><p>${favorites.length} قطعة في مفضلتك، محفوظة على هذا الجهاز.</p></div><div class="product-grid">${favorites.length?favorites.map(id=>card(product(id))).join(''):empty('مفضلتك تبدأ بقطعة','اضغط القلب على أي قطعة لحفظها هنا.','اكتشف المجموعة','#catalog')}</div></div>`}
function modal(html){closeLayers(false);lastFocus=document.activeElement;$('#modal').innerHTML='<button class="close" data-action="close" aria-label="إغلاق">✕</button>'+html;$('#shade').hidden=false;$('#modal').hidden=false;document.body.classList.add('locked');$('#modal .close').focus()}
function closeLayers(restore=true){$('#drawer').hidden=true;$('#modal').hidden=true;$('#shade').hidden=true;document.body.classList.remove('locked');if(restore&&lastFocus?.isConnected)lastFocus.focus()}
function openQuick(id){quickId=id;chosenSize=null;const p=product(id);modal(`<div class="modal-product"><div class="modal-art">${sprite(p)}</div>${productOptions(p,true)}</div>`)}
function openCart(){if(location.hash==='#checkout'&&checkoutStep===1&&$('#checkoutForm'))checkoutData=Object.fromEntries(new FormData($('#checkoutForm')));closeLayers(false);lastFocus=document.activeElement;$('#drawer').setAttribute('aria-label','حقيبة التسوق');renderCart();$('#drawer').hidden=false;$('#shade').hidden=false;document.body.classList.add('locked');$('#drawer .close').focus()}
function renderCart(){const t=totals(),remaining=Math.max(0,75-t.net);$('#drawer').innerHTML=`<div class="drawer-head"><h2>حقيبتك <small>(${cart.reduce((s,c)=>s+c.qty,0)})</small></h2><button class="close" data-action="close" aria-label="إغلاق">✕</button></div><div class="drawer-body">${cart.length?`<div class="shipping-progress">${remaining?`أضف ${money(remaining)} لشحن عادي مجاني في النموذج`:'وصلت إلى الشحن العادي المجاني في النموذج'}<div class="progress-track"><i style="width:${Math.min(100,t.net/75*100)}%"></i></div></div>${cart.map((c,i)=>{const p=product(c.id);return `<div class="cart-item"><a class="cart-thumb" href="#product/${p.id}">${sprite(p)}</a><div class="cart-info"><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.color} / ${c.size}</p>${price(p)}<div class="quantity-row"><div class="quantity"><button data-action="qty" data-index="${i}" data-delta="-1" aria-label="تقليل كمية ${p.name}">−</button><span>${c.qty}</span><button data-action="qty" data-index="${i}" data-delta="1" aria-label="زيادة كمية ${p.name}" ${c.qty>=p.stock?'disabled':''}>+</button></div><button class="remove" data-action="remove" data-index="${i}">إزالة</button></div></div></div>`}).join('')}`:empty('حقيبتك تنتظر أول قطعة','ابدأ باكتشاف ما يشبهك.','تسوّق المجموعة','#catalog')}</div>${cart.length?`<div class="drawer-bottom"><form class="coupon" id="couponForm"><input aria-label="كود الخصم" placeholder="كود الخصم" value="${coupon}"><button type="submit">تطبيق</button></form><div class="coupon-note">${coupon?'تم تطبيق LOOP10 — خصم 10% <button data-action="remove-coupon">إزالة ×</button>':'جرّب الكود LOOP10 لخصم تجريبي 10%'}</div><div class="cart-total"><span>مجموع القطع</span><strong>${money(t.net)}</strong></div><p class="cart-small">الشحن يُحسب في الخطوة التالية. الطلب تجريبي ولا يتم تحصيل مبالغ.</p><a href="#checkout" class="btn full">متابعة الطلب التجريبي ${icon('arrow')}</a></div>`:''}`}
function addToCart(id){const p=product(id),scope=$('#modal').hidden?$('#app'):$('#modal');if(!chosenSize){scope.querySelector('.size-error').textContent='اختر المقاس أولاً.';scope.querySelector('.size-options button:not(:disabled)')?.focus();return}const row=cart.find(c=>c.id===id&&c.size===chosenSize);const qty=cart.filter(c=>c.id===id).reduce((s,c)=>s+c.qty,0);if(qty>=p.stock){toast('وصلت إلى الكمية المتاحة من هذه القطعة في النموذج.');return}if(row)row.qty++;else cart.push({id,size:chosenSize,qty:1});persist();closeLayers();toast('أُضيفت '+p.name+' إلى حقيبتك ✓')}
function sizeGuide(){modal(`<span class="eyebrow">FIND YOUR FIT</span><h2>دليل المقاسات</h2><p>قياسات توضيحية بالسنتيمتر. القصّة الفعلية تختلف حسب المنتج.</p><table class="size-table"><thead><tr><th>المقاس</th><th>الصدر</th><th>الخصر</th><th>الورك</th></tr></thead><tbody>${[['S','88–94','72–78','90–96'],['M','95–101','79–85','97–103'],['L','102–108','86–92','104–110'],['XL','109–115','93–99','111–117']].map(r=>'<tr>'+r.map(c=>'<td dir="ltr">'+c+'</td>').join('')+'</tr>').join('')}</tbody></table><p>الأحذية بالمقاس الأوروبي (EU). الإكسسوارات والحقائب بمقاس موحّد. المقاسات المشطوبة غير متاحة في النموذج.</p>`)}
function orderSummary(){const t=totals();return `<aside class="order-summary"><h2>ملخص طلبك</h2>${cart.map(c=>{const p=product(c.id);return `<div class="summary-item"><div class="cart-thumb">${sprite(p)}</div><div>${p.name}<small>${p.color} / ${c.size} × ${c.qty}</small></div><span>${money(p.price*c.qty)}</span></div>`}).join('')}<div class="summary-line"><span>المنتجات</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-line"><span>خصم LOOP10</span><span>− ${money(t.discount)}</span></div>`:''}<div class="summary-line"><span>الشحن ${delivery==='express'?'السريع':'العادي'} (تجريبي)</span><span>${t.shipping?money(t.shipping):'مجاني'}</span></div><div class="summary-line grand"><span>الإجمالي</span><span>${money(t.total)}</span></div><p class="cart-small">لا توجد عملية دفع حقيقية، ولن يتم إرسال طلب إلى تاجر.</p></aside>`}
function checkout(){if(!cart.length)return '<div class="container">'+empty('حقيبتك فارغة','أضف قطعة لتجربة خطوات الطلب.','الذهاب للمتجر','#catalog')+'</div>';return `<div class="container"><div class="page-heading"><div class="breadcrumb"><a href="#catalog">المتجر</a><span>/</span><span>إتمام الطلب</span></div><h1>خطوة أقرب لاختيارك.</h1></div><div class="demo-notice">هذه تجربة طلب فقط. استخدم بيانات وهمية؛ لن يتم تحصيل مبلغ أو إرسال طلب. بيانات العنوان لا تُحفظ بعد مغادرة الصفحة.</div><div class="checkout-steps">${['بيانات التوصيل','طريقة التوصيل','مراجعة الطلب'].map((s,i)=>`<span class="${checkoutStep===i+1?'active':''}">${i+1}. ${s}</span>`).join('')}</div><div class="checkout-layout"><form class="checkout-form" id="checkoutForm">${checkoutStep===1?`<h2>إلى أين تتجه اختياراتك؟</h2><div class="form-grid"><label class="form-field wide">الاسم التجريبي<input name="name" required minlength="2" maxlength="80" autocomplete="off" placeholder="مثال: زائر المتجر" value="${esc(checkoutData.name||'')}"></label><label class="form-field">رقم هاتف تجريبي<input name="phone" type="tel" required pattern="[+0-9 ()-]{8,20}" maxlength="20" autocomplete="off" placeholder="0790000000" value="${esc(checkoutData.phone||'')}"></label><label class="form-field">المدينة<select name="city" required><option value="">اختر المدينة</option>${['عمّان','إربد','الزرقاء','العقبة','السلط','مادبا','جرش','عجلون','الكرك','المفرق','معان','الطفيلة'].map(c=>`<option ${checkoutData.city===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="form-field wide">عنوان تجريبي<input name="address" required minlength="5" maxlength="180" autocomplete="off" placeholder="شارع التجربة، مبنى 1" value="${esc(checkoutData.address||'')}"></label><label class="form-field wide">ملاحظات (اختياري)<textarea name="notes" maxlength="300" placeholder="أي ملاحظات لتجربة الطلب">${esc(checkoutData.notes||'')}</textarea></label></div><div class="checkout-actions"><button type="submit" class="btn">متابعة إلى التوصيل ←</button><button type="button" data-action="cart" class="text-link">تعديل الحقيبة</button></div>`:checkoutStep===2?`<h2>طريقة التوصيل</h2><p class="cart-small">خيارات وتكاليف تجريبية فقط.</p><label class="delivery-choice"><input type="radio" name="delivery" value="standard" ${delivery==='standard'?'checked':''}><span>توصيل عادي<small>2–4 أيام عمل في النموذج</small></span><strong>${totals().net>=75?'مجاني':'3 د.أ'}</strong></label><label class="delivery-choice"><input type="radio" name="delivery" value="express" ${delivery==='express'?'checked':''}><span>توصيل سريع<small>1–2 يوم عمل في النموذج</small></span><strong>7 د.أ</strong></label><p class="cart-small">الشحن العادي مجاني عندما يصل مجموع القطع بعد الخصم إلى 75 د.أ.</p><div class="checkout-actions"><button type="submit" class="btn">مراجعة الطلب ←</button><button type="button" data-action="checkout-back" class="text-link">رجوع</button></div>`:`<h2>كل شيء في مكانه؟</h2><div class="review-box"><h3>بيانات التوصيل</h3>${esc(checkoutData.name)}<br>${esc(checkoutData.city)} — ${esc(checkoutData.address)}<br><span dir="ltr">${esc(checkoutData.phone)}</span><br>${checkoutData.notes?esc(checkoutData.notes):''}<br><button type="button" data-action="checkout-edit" class="text-link">تعديل البيانات</button></div><div class="review-box"><h3>طريقة الدفع</h3>محاكاة فقط — لا بطاقة، ولا تحصيل مبالغ.<br>التوصيل: ${delivery==='express'?'سريع':'عادي'} (تجريبي).</div><label class="check-line"><input type="checkbox" name="agree" required><span>أفهم أن هذا طلب تجريبي محفوظ على هذا الجهاز فقط، ولا يترتب عليه شراء أو توصيل.</span></label><div class="checkout-actions"><button type="submit" class="btn">إنشاء طلب تجريبي ${icon('check')}</button><button type="button" data-action="checkout-back" class="text-link">رجوع</button></div>`}</form>${orderSummary()}</div></div>`}
function finishOrder(){const t=totals(),id='DEMO-'+Date.now().toString(36).toUpperCase();orders.unshift({id,date:new Date().toISOString(),items:cart.map(c=>({...c})),...t,delivery});orders=orders.slice(0,20);cart=[];coupon='';checkoutData={};checkoutStep=1;persist();location.hash='success/'+id}
function success(id){const o=orders.find(x=>x.id===id);if(!o)return orderPage();return `<section class="success"><div class="success-mark">✓</div><span class="eyebrow">YOUR DEMO ORDER</span><h1>اكتملت التجربة.</h1><p>حُفظ ملخص طلبك على هذا الجهاز.<br>لم يتم إرسال طلب أو خصم أي مبلغ.</p><span class="receipt-number">${o.id}</span><p>${o.items.reduce((s,c)=>s+c.qty,0)} قطع · إجمالي تجريبي ${money(o.total)}</p><div class="hero-actions" style="justify-content:center"><a class="btn" href="#catalog">تابع اكتشاف المجموعة ←</a><a class="btn outline" href="#orders">طلباتي التجريبية</a></div></section>`}
function orderPage(){return `<div class="container"><div class="page-heading"><span class="eyebrow">YOUR LOCAL ARCHIVE</span><h1>طلباتك التجريبية</h1><p>ملخصات محفوظة على هذا المتصفح فقط، بدون بيانات عنوان أو هاتف.</p></div>${orders.length?orders.map(o=>`<article class="order-card"><div class="order-card-head"><strong>${esc(o.id)}</strong><span>${new Date(o.date).toLocaleDateString('ar-JO')} · تجربة مكتملة، لم تُرسل</span></div><p>${o.items.map(c=>`${esc(product(c.id)?.name||'قطعة')} (${esc(c.size)}) × ${c.qty}`).join(' / ')}</p><div class="cart-total"><span>الإجمالي التجريبي</span><strong>${money(o.total)}</strong></div><button class="text-link" data-action="reorder" data-id="${esc(o.id)}">إضافة القطع للحقيبة مجدداً ←</button></article>`).join(''):empty('لا توجد طلبات تجريبية بعد','بعد إتمام تجربة الطلب، ستجد ملخّصها هنا.','ابدأ التسوّق','#catalog')}</div>`}
function help(){return `<div class="container help-page"><div class="page-heading"><span class="eyebrow">A LITTLE HELP</span><h1>كل ما تحتاج معرفته.</h1><p>دليل واضح لتجربة LOOP الحالية.</p></div><section class="help-section" id="shipping"><h2>الشحن والطلب</h2><details open><summary>هل يمكنني الشراء فعلياً؟</summary><p>المتجر نسخة تفاعلية تجريبية. يمكنك تصفح 36 منتجاً وتجربة السلة والخصم وخطوات الطلب. لا يوجد دفع أو شحن فعلي، ولا يتم إرسال الطلبات إلى تاجر.</p></details><details><summary>كيف تُحسب تكلفة الشحن في النموذج؟</summary><p>التوصيل العادي 3 د.أ، ويصبح مجانياً للطلبات التي تبلغ 75 د.أ بعد الخصم. التوصيل السريع 7 د.أ. جميع المدد والتكاليف توضيحية وليست تعهداً بخدمة فعلية.</p></details><details><summary>هل توجد سياسة استبدال أو إرجاع؟</summary><p>لا توجد معاملات بيع فعلية في هذه النسخة. يجب إضافة سياسة التاجر الحقيقية وبيانات التواصل قبل إطلاق البيع.</p></details><details><summary>كيف أستخدم كود الخصم؟</summary><p>افتح الحقيبة وأدخل LOOP10 للحصول على خصم تجريبي 10% على قيمة المنتجات. يمكن استخدام كود واحد فقط، ولا يشمل تكلفة الشحن.</p></details></section><section class="help-section" id="sizes"><h2>المنتجات والمقاسات</h2><details open><summary>كيف أختار المقاس؟</summary><p>افتح صفحة القطعة ثم اختر المقاس المتاح. استخدم دليل المقاسات للمقارنة، والمقاسات المشطوبة غير متاحة في النموذج.</p><button class="text-link" data-action="size-guide">فتح دليل المقاسات ←</button></details><details><summary>هل المنتجات والصور حقيقية؟</summary><p>المنتجات والأسعار والمخزون تجريبية. صور الأزياء مُولّدة لتوضيح التصميم، وبعض خيارات الألوان معاينات رقمية لنفس التصميم وليست صوراً لمخزون تجاري.</p></details></section><section class="help-section"><h2>المفضلة والخصوصية</h2><details><summary>أين تُحفظ حقيبتي ومفضلتي؟</summary><p>تُحفظ في متصفحك على هذا الجهاز. لا يوجد حساب أو مزامنة بين الأجهزة. مسح بيانات المتصفح قد يحذف اختياراتك.</p></details><details><summary>هل تُحفظ بيانات التوصيل؟</summary><p>لا تُحفظ في التخزين المحلي ولا تُرسل لأي جهة. تبقى مؤقتاً في الصفحة أثناء الخطوات وتُمسح عند اكتمال الطلب أو مغادرة صفحة إتمام الطلب. استخدم بيانات وهمية للتجربة.</p></details></section><a class="btn" href="#catalog">العودة إلى المجموعة ←</a></div>`}
let previousRoute='';function render(scroll=true){closeLayers(false);const route=location.hash.slice(1).split('?')[0]||'home';if(previousRoute==='checkout'&&route!=='checkout'){checkoutData={};checkoutStep=1}previousRoute=route;document.body.classList.toggle('shelf-view',['room/shoes','room/bags','room/accessories'].includes(route));document.body.classList.toggle('mall-home',route==='home'||route==='cart');document.body.classList.toggle('immersive',route==='home'||route==='cart'||route.startsWith('room/'));chosenSize=null;quickId=null;$('#app').innerHTML=route==='home'?home():route.startsWith('room/')?roomPage(route.split('/')[1]):route==='catalog'?catalog():route.startsWith('product/')?productPage(route.split('/')[1]):route==='favorites'?favoritePage():route==='checkout'?checkout():route==='orders'?orderPage():route.startsWith('success/')?success(route.split('/')[1]):route==='help'?help():route==='cart'?home():home();document.title=(route==='catalog'?'المجموعة':route.startsWith('product/')?(product(route.split('/')[1])?.name||'المنتج'):route==='checkout'?'إتمام الطلب':route==='favorites'?'المفضلة':'أسلوبك خارج المألوف')+' — LOOP';updateHeader();if(route==='home'||route==='cart')setupMall();if(route.startsWith('room/'))setupRoom();if(scroll)window.scrollTo({top:0,behavior:'instant'});if(route==='cart')openCart();if(route==='help'&&params().get('s'))document.getElementById(params().get('s'))?.scrollIntoView({behavior:'instant'});}
function openMenu(){closeLayers(false);lastFocus=document.activeElement;$('#drawer').setAttribute('aria-label','قائمة المتجر');$('#drawer').innerHTML=`<div class="drawer-head"><a class="logo" href="#home">loop<span>®</span></a><button class="close" data-action="close" aria-label="إغلاق">✕</button></div><div class="drawer-body menu-links">${[['#home','داخل محل LOOP'],['#room/men','رجالي'],['#room/women','نسائي'],['#room/shoes','أحذية'],['#room/bags','حقائب'],['#room/accessories','إكسسوارات'],['#catalog?new=1','وصل حديثاً'],['#catalog?sale=1','العروض'],['#catalog','البحث في كل المنتجات'],['#favorites','المفضلة'],['#orders','طلباتي التجريبية'],['#help','المساعدة']].map(([h,t])=>`<a href="${h}">${t}<span>←</span></a>`).join('')}<p class="micro">LOOP / FALL 2026</p></div>`;$('#drawer').hidden=false;$('#shade').hidden=false;document.body.classList.add('locked');$('#drawer .close').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){const a=e.target.closest('a[href^="#"]');if(a){closeLayers(false);if(a.hash===location.hash)render()}return}const a=b.dataset.action,id=b.dataset.id;
if(a==='search'){$('#searchBar').hidden=!$('#searchBar').hidden;if(!$('#searchBar').hidden)$('#searchInput').focus()}
if(a==='menu')openMenu();if(a==='cart')openCart();if(a==='close')closeLayers();if(a==='quick')openQuick(id);if(a==='size-guide')sizeGuide();
if(a==='favorite'){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();document.querySelectorAll(`[data-action="favorite"][data-id="${id}"]`).forEach(btn=>{const active=favorites.includes(id);btn.classList.toggle('selected',active);btn.setAttribute('aria-pressed',active);btn.setAttribute('aria-label',(active?'إزالة من':'إضافة إلى')+' المفضلة: '+product(id).name)});if(location.hash.startsWith('#favorites'))render(false);toast(favorites.includes(id)?'أُضيفت إلى مفضلتك ♡':'أُزيلت من المفضلة')}
if(a==='size'){chosenSize=b.dataset.size;b.closest('.size-options').querySelectorAll('button').forEach(btn=>{btn.classList.toggle('selected',btn===b);btn.setAttribute('aria-pressed',btn===b)});b.closest('.product-summary').querySelector('.size-error').textContent=''}
if(a==='add')addToCart(id);if(a==='zoom'){const g=$('#gallery');g.classList.toggle('zoomed');b.textContent=g.classList.contains('zoomed')?'تصغير الصورة −':'تكبير الصورة +'}
if(a==='qty'){const i=+b.dataset.index,c=cart[i];const otherQty=cart.filter((r,j)=>j!==i&&r.id===c.id).reduce((s,r)=>s+r.qty,0);if(+b.dataset.delta>0&&c.qty+otherQty>=product(c.id).stock){toast('وصلت إلى الكمية المتاحة في النموذج.');return}c.qty+=+b.dataset.delta;if(c.qty<=0)cart.splice(i,1);persist();renderCart();if(location.hash==='#checkout')$('#app').innerHTML=checkout()}
if(a==='remove'){cart.splice(+b.dataset.index,1);persist();renderCart();if(location.hash==='#checkout')$('#app').innerHTML=checkout()}
if(a==='remove-coupon'){coupon='';persist();renderCart();if(location.hash==='#checkout')$('#app').innerHTML=checkout()}
if(a==='filters'){filtersExpanded=!filtersExpanded;$('#filters').classList.toggle('open',filtersExpanded);b.setAttribute('aria-expanded',$('#filters').classList.contains('open'))}
if(a==='remove-filter')location.hash=catalogURL({[b.dataset.key]:''});if(a==='reset-filters')location.hash='#catalog';if(a==='more'){const y=scrollY;visibleCount+=12;$('#app').innerHTML=catalog();scrollTo(0,y)}
if(a==='checkout-back'){checkoutStep=Math.max(1,checkoutStep-1);render()}if(a==='checkout-edit'){checkoutStep=1;render()}
if(a==='reorder'){const o=orders.find(x=>x.id===id);o.items.forEach(c=>{const p=product(c.id);if(!p||p.unavailable.includes(c.size))return;const existing=cart.find(x=>x.id===c.id&&x.size===c.size),used=cart.filter(x=>x.id===c.id).reduce((s,x)=>s+x.qty,0),add=Math.min(c.qty,Math.max(0,p.stock-used));if(!add)return;if(existing)existing.qty+=add;else cart.push({...c,qty:add})});persist();openCart()}
if(a==='hero'){heroIndex=+b.dataset.index;const p=PRODUCTS[[2,4,5][heroIndex]];$('#heroPiece').innerHTML=sprite(p);$('#heroTag').innerHTML=p.name+' / '+p.color+'<span>اكتشف القطعة ↗</span>';$('#heroTag').href='#product/'+p.id;document.querySelectorAll('[data-action="hero"]').forEach(x=>x.classList.toggle('active',x===b))}
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='sort')location.hash=catalogURL({sort:t.value});if(t.name==='gender')location.hash=catalogURL({gender:t.value});if(t.id==='priceRange')location.hash=catalogURL({max:+t.value===100?'':t.value});if(t.id==='sizeFilter')location.hash=catalogURL({size:t.value});if(t.id==='saleFilter')location.hash=catalogURL({sale:t.checked?'1':''});if(t.id==='newFilter')location.hash=catalogURL({new:t.checked?'1':''});if(t.name==='delivery'){delivery=t.value;const summary=$('.order-summary');summary.outerHTML=orderSummary()}});
document.addEventListener('input',e=>{if(e.target.id==='priceRange')$('#priceOutput').textContent=money(e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='searchForm'){e.preventDefault();const q=$('#searchInput').value.trim();$('#searchBar').hidden=true;location.hash=catalogURL({q},true)}if(e.target.id==='couponForm'){e.preventDefault();const value=e.target.querySelector('input').value.trim().toUpperCase();if(value==='LOOP10'){coupon=value;persist();renderCart();if(location.hash==='#checkout')$('#app').innerHTML=checkout();toast('تم تطبيق خصم 10%')}else toast('الكود غير صالح. جرّب LOOP10.')}if(e.target.id==='checkoutForm'){e.preventDefault();if(!e.target.reportValidity())return;if(checkoutStep===1){checkoutData=Object.fromEntries(new FormData(e.target));checkoutStep=2;render()}else if(checkoutStep===2){checkoutStep=3;render()}else finishOrder()}});
$('#shade').onclick=()=>closeLayers();document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeLayers();$('#searchBar').hidden=true}if(e.key==='Tab'){const layer=!$('#modal').hidden?$('#modal'):!$('#drawer').hidden?$('#drawer'):null;if(layer){const els=[...layer.querySelectorAll('button:not(:disabled),a[href],input,select,textarea')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}}});
window.addEventListener('hashchange',()=>{visibleCount=12;render()});window.addEventListener('storage',e=>{if(e.key==='loop-store-cart')location.reload()});$('#searchToggle').innerHTML=icon('search');$('#searchIcon').innerHTML=icon('search');$('#bagIcon').innerHTML=icon('bag');$('#menuToggle').innerHTML=icon('menu');render();
